const H: HexagramEntry[] = D.map((d: any) => {
  const u = TR[d[3]], l = TR[d[4]];
  const mt = (t: any) => ({ name: { en: t.en, zh: t.zh, ja: t.ja }, symbol: t.sym, meaning: { en: t.m.en, zh: t.m.zh, ja: t.m.ja } });
  const lt = (en: string, zh: string, ja: string) => ({ en, zh, ja });
  const dr = (i: number): DomainReading => ({
    analysis: { en: d[i], zh: d[i+1], ja: d[i+2] },
    advice: { en: d[i+3], zh: d[i+4], ja: d[i+5] },
  });
  return {
    name: { en: d[0], zh: d[1], ja: d[2] },
    upperTrigram: mt(u),
    lowerTrigram: mt(l),
    fiveElement: lt(d[5], d[5], d[5]),
    direction: lt(d[6], d[6], d[6]),
    guaCi: { en: d[7], zh: d[8], ja: d[9] },
    daXiang: { en: d[10], zh: d[11], ja: d[12] },
    domains: {
      love: dr(13),
      wealth: dr(19),
      career: dr(25),
      health: dr(31),
      study: dr(37),
      decision: dr(43),
    },
  };
});

export function lookupHexagram(idx: number): HexagramEntry { return H[idx % 64]; }